                <input id="address" type="text" @bind="Address" class="form-control" />
            </div>
            <div class="step-buttons">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsProcessing">
                    @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
                </button>
            </div>
        </section>
        break;

    case 1:
        @* Step 2 — Work History *@
        <section class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <h4>Position @(index + 1)</h4>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-danger btn-sm remove-btn" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="WorkEntries[index].Company" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="WorkEntries[index].Title" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="WorkEntries[index].StartDate" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" @bind="WorkEntries[index].IsCurrent" /> Currently working here
                        </label>
                    </div>
                    @if (!WorkEntries[index].IsCurrent)
                    {
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="WorkEntries[index].EndDate" class="form-control" />
                        </div>
                    }
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea @bind="WorkEntries[index].Description" class="form-control" rows="3"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-buttons">
                <button class="btn btn-outline" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </section>
        break;

    case 2:
        @* Step 3 — References *@
        <section class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <h4>Reference @(index + 1)</h4>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-danger btn-sm remove-btn" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="References[index].Name" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="References[index].Relationship" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="References[index].Email" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="References[index].Phone" class="form-control" />
                    </div>
                </div>
            }
            @if (References.Count < 3)
            {
                <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn btn-outline" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
        break;

    case 3:
        @* Step 4 — Cover Letter *@
        <section class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <textarea @bind="CoverLetter" @bind:event="oninput" class="form-control cover-letter-textarea" rows="12" maxlength="2000"></textarea>
                <div class="character-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="step-buttons">
                <button class="btn btn-outline" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </section>
        break;

    case 4:
        @* Step 5 — Review & Submit *@
        <section class="step-content">
            @if (IsSubmitted)
            {
                <div class="submission-confirmation">
                    <h2>&#10003; Application Submitted!</h2>
                    <p>Your application has been submitted successfully.</p>
                    <p><strong>Application ID: @ApplicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <h3>Personal Information <a class="edit-link" @onclick="() => GoToStep(0)">Edit</a></h3>
                    <dl>
                        <dt>Full Name</dt><dd>@FullName</dd>
                        <dt>Email</dt><dd>@Email</dd>
                        <dt>Phone</dt><dd>@Phone</dd>
                        <dt>Address</dt><dd>@Address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <h3>Work History <a class="edit-link" @onclick="() => GoToStep(1)">Edit</a></h3>
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span><br />
                            <p>@entry.Description</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>References <a class="edit-link" @onclick="() => GoToStep(2)">Edit</a></h3>
                    @foreach (var reference in References)
                    {
                        <div class="review-entry">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>Cover Letter <a class="edit-link" @onclick="() => GoToStep(3)">Edit</a></h3>
                    <p class="cover-letter-preview">@CoverLetter</p>
                </div>

                <div class="step-buttons">
                    <button class="btn btn-outline" @onclick="Back">Back</button>
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                    </button>
                </div>
            }
        </section>
        break;
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsProcessing { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }

    // Step 1 - Personal Info
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 - Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ErrorMessage = string.Empty;
        }
    }

    private void GoToStep(int stepIndex)
    {
        CurrentStep = stepIndex;
        ErrorMessage = string.Empty;
    }

    private void Back()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsProcessing = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
            CurrentStep++;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = string.Empty;

        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
            {
                ErrorMessage = "Please fill in all required fields for each work entry.";
                return;
            }
        }

        CurrentStep++;
    }

    private void NextFromReferences()
    {
        ErrorMessage = string.Empty;

        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                ErrorMessage = "Please fill in all required fields for each reference.";
                return;
            }
        }

        CurrentStep++;
    }

    private void NextFromCoverLetter()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please provide a cover letter.";
            return;
        }

        CurrentStep++;
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        ErrorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetter);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
"}

